import fs from 'fs';
import path from 'path';

/**
 * Generates automated Playwright multi-viewport and accessibility test suites.
 */
export function generateQATests(outDir = './e2e') {
  const targetDir = path.resolve(process.cwd(), outDir);
  fs.mkdirSync(targetDir, { recursive: true });

  // 1. e2e/a11y.spec.ts (WCAG 2.2 AA Automated Runner)
  const a11ySpec = `import { test, expect } from '@playwright/test';
import AxeBuilder from '@axe-core/playwright';

/**
 * Automated WCAG 2.2 AA Accessibility & Viewport Overflow Test Suite
 * Generated by Agentway gen:playwright
 */

const viewports = [
  { name: 'Mobile Small (iPhone SE)', width: 375, height: 667 },
  { name: 'Mobile Standard (iPhone 15)', width: 393, height: 852 },
  { name: 'Tablet (iPad)', width: 768, height: 1024 },
  { name: 'Desktop Large', width: 1280, height: 800 }
];

test.describe('Accessibility & Responsive Viewport Matrix', () => {
  for (const vp of viewports) {
    test(\`Verify no WCAG violations on \${vp.name}\`, async ({ page }) => {
      await page.setViewportSize({ width: vp.width, height: vp.height });
      await page.goto('/');

      // 1. Axe-core WCAG 2.2 AA Scan
      const accessibilityScanResults = await new AxeBuilder({ page })
        .withTags(['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'])
        .analyze();

      expect(accessibilityScanResults.violations).toEqual([]);

      // 2. Horizontal Overflow Check
      const hasHorizontalScrollbar = await page.evaluate(() => {
        return document.documentElement.scrollWidth > window.innerWidth;
      });

      expect(hasHorizontalScrollbar).toBeFalsy();
    });
  }
});
`;
  fs.writeFileSync(path.join(targetDir, 'a11y.spec.ts'), a11ySpec, 'utf-8');

  // 2. e2e/flow.spec.ts (Core Critical Path Verification)
  const flowSpec = `import { test, expect } from '@playwright/test';

/**
 * Core User Flow Functional Test
 * Generated by Agentway gen:playwright
 */

test.describe('Critical Path User Journey', () => {
  test('User can navigate without dead ends or missing action handlers', async ({ page }) => {
    await page.goto('/');

    // Verify main navigation links
    const navLinks = page.locator('nav a');
    const count = await navLinks.count();
    
    for (let i = 0; i < count; i++) {
      const link = navLinks.nth(i);
      const href = await link.getAttribute('href');
      expect(href).not.toBe('#');
      expect(href).not.toBe('');
    }

    // Verify primary action button exists
    const primaryBtn = page.locator('button.btn-primary, button[type="submit"]').first();
    if (await primaryBtn.isVisible()) {
      await expect(primaryBtn).toBeEnabled();
    }
  });
});
`;
  fs.writeFileSync(path.join(targetDir, 'flow.spec.ts'), flowSpec, 'utf-8');

  return {
    testDir: targetDir,
    files: ['a11y.spec.ts', 'flow.spec.ts']
  };
}
